param(  [string]$Project = "knowing-mind-app",  [string]$Region = "asia-southeast1",  [string]$ServiceName = "kma-api",  [string]$IngestPath = "/api/cdh/ingest",  [string]$InvokerServiceAccount = "svc-runtime@knowing-mind-app.iam.gserviceaccount.com")$root = "$env:USERPROFILE\knowingmind-vault\KMS_CDH"$snapshots = Join-Path $root "snapshots"$docs = Join-Path $root "docs"New-Item -ItemType Directory -Force -Path $snapshots | Out-NullNew-Item -ItemType Directory -Force -Path $docs | Out-Null# 1. เขียนไฟล์ snapshot ล่าสุด@'{  "generated_at_local": "' + (Get-Date -Format "yyyy-MM-ddTHH:mm:sszzz") + '",  "tasks": {    "done": [ "Meta API init", "Test OSP/OST bundles" ],    "next": [ "Wire Meta App→Webhook (kma-api)", "OST9 readiness on MS Horse" ],    "blockers": [ "Some GitHub perms", "Waiting API keys" ],    "notes": "Landing split into 3 groups"  }}'@ | Out-File -Encoding UTF8 -FilePath (Join-Path $snapshots "kms_tasks_latest.json")# 2. เขียน Agreement$agreement = @"# Agreement ($(Get-Date -Format "dd MMMM yyyy"))## ข้อตกลงจากการสนทนา(…ตามที่สรุปด้านบน…)"@$agreement | Out-File -Encoding UTF8 -FilePath (Join-Path $docs "AGREEMENT_$(Get-Date -Format 'yyyy-MM-dd').md")# 3. ส่งไฟล์ขึ้น Cloud Run ingest$payload = Get-Content (Join-Path $snapshots "kms_tasks_latest.json") -Raw$url = "https://$ServiceName-$Region.a.run.app$IngestPath"Write-Host "→ POST $url"Invoke-RestMethod -Uri $url -Method Post -Body $payload -ContentType "application/json" `  -Headers @{ "Authorization" = "Bearer $(gcloud auth print-identity-token)" }Write-Host "✓ อัปเดต snapshot + agreement สำเร็จ"